using AISmartLearning.API.Models;
using Microsoft.EntityFrameworkCore;
namespace AISmartLearning.API.Data;
public sealed class AppDbContext(DbContextOptions<AppDbContext> options) : DbContext(options) {
 public DbSet<Role> Roles=>Set<Role>(); public DbSet<User> Users=>Set<User>(); public DbSet<Conversation> Conversations=>Set<Conversation>(); public DbSet<ConversationMessage> ConversationMessages=>Set<ConversationMessage>(); public DbSet<InteractionLog> InteractionLogs=>Set<InteractionLog>();
 protected override void OnModelCreating(ModelBuilder b) {
  b.Entity<Role>(e=>{e.ToTable("Roles");e.HasKey(x=>x.RoleId);e.Property(x=>x.RoleName).HasMaxLength(30).IsRequired();e.HasIndex(x=>x.RoleName).IsUnique();});
  b.Entity<User>(e=>{e.ToTable("Users");e.HasKey(x=>x.UserId);e.Property(x=>x.FullName).HasMaxLength(120).IsRequired();e.Property(x=>x.Email).HasMaxLength(256).IsRequired();e.Property(x=>x.PasswordHash).HasMaxLength(500).IsRequired();e.HasIndex(x=>x.Email).IsUnique();e.HasIndex(x=>x.RoleId);e.Property(x=>x.CreatedAt).HasDefaultValueSql("SYSUTCDATETIME()");e.HasOne(x=>x.Role).WithMany(x=>x.Users).HasForeignKey(x=>x.RoleId).OnDelete(DeleteBehavior.Restrict);});
  b.Entity<Conversation>(e=>{e.ToTable("Conversations", table => table.HasCheckConstraint("CK_Conversations_Status","[Status] IN ('Active','Completed')"));e.HasKey(x=>x.ConversationId);e.Property(x=>x.Title).HasMaxLength(200).IsRequired();e.Property(x=>x.Status).HasMaxLength(20).IsRequired();e.HasIndex(x=>new{x.UserId,x.StartedAt});e.Property(x=>x.StartedAt).HasDefaultValueSql("SYSUTCDATETIME()");e.HasOne(x=>x.User).WithMany(x=>x.Conversations).HasForeignKey(x=>x.UserId).OnDelete(DeleteBehavior.Cascade);});
  b.Entity<ConversationMessage>(e=>{e.ToTable("ConversationMessages", table => table.HasCheckConstraint("CK_ConversationMessages_SenderType","[SenderType] IN ('User','AI')"));e.HasKey(x=>x.MessageId);e.Property(x=>x.MessageText).IsRequired();e.Property(x=>x.SenderType).HasMaxLength(10).IsRequired();e.HasIndex(x=>new{x.ConversationId,x.CreatedAt});e.Property(x=>x.CreatedAt).HasDefaultValueSql("SYSUTCDATETIME()");e.HasOne(x=>x.Conversation).WithMany(x=>x.Messages).HasForeignKey(x=>x.ConversationId).OnDelete(DeleteBehavior.Cascade);});
  b.Entity<InteractionLog>(e=>{e.ToTable("InteractionLogs");e.HasKey(x=>x.LogId);e.Property(x=>x.Action).HasMaxLength(100).IsRequired();e.Property(x=>x.Details).HasMaxLength(2000).IsRequired();e.HasIndex(x=>x.CreatedAt);e.HasIndex(x=>new{x.UserId,x.CreatedAt});e.Property(x=>x.CreatedAt).HasDefaultValueSql("SYSUTCDATETIME()");e.HasOne(x=>x.User).WithMany(x=>x.InteractionLogs).HasForeignKey(x=>x.UserId).OnDelete(DeleteBehavior.Restrict);e.HasOne(x=>x.Conversation).WithMany().HasForeignKey(x=>x.ConversationId).OnDelete(DeleteBehavior.SetNull);});
 }
}